<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Sorting Visualizer</title>
<style>
  :root {
    --bg: #121212;
    --fg: #e0e0e0;
    --accent: #4af;
    --accent-dim: #28f;
    --button-bg: #1e1e1e;
    --button-hover: #2a2a2a;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: var(--bg);
    color: var(--fg);
    font-family: system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 20px;
  }
  h1 { margin: 0 0 16px; font-size: 1.5rem; }
  .controls {
    display: flex;
    gap: 12px;
    margin-bottom: 16px;
  }
  button {
    padding: 10px 20px;
    font-size: 1rem;
    background: var(--button-bg);
    color: var(--fg);
    border: 1px solid #333;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.2s;
  }
  button:hover { background: var(--button-hover); }
  button:disabled { opacity: 0.5; cursor: not-allowed; }
  #bars {
    width: 100%;
    max-width: 900px;
    height: 60vh;
    min-height: 300px;
    background: #0d0d0d;
    border: 1px solid #222;
    border-radius: 4px;
    display: flex;
    align-items: flex-end;
    gap: 1px;
    padding: 10px;
    overflow: hidden;
  }
  .bar {
    flex: 1;
    background: linear-gradient(to top, var(--accent), var(--accent-dim));
    border-radius: 2px 2px 0 0;
    transition: height 50ms linear, background 50ms;
  }
  .bar.compare { background: #f80; }
  .bar.swapped { background: #0f8; }
</style>
</head>
<body>
<h1>Sorting Algorithm Visualizer</h1>
<div class="controls">
  <button id="sort">Sort</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
</div>
<div id="bars"></div>

<script>
/* ---------- Core sorting logic ---------- */
let arr = [];
let sortState = null; // { i, j, n }
let lastCompared = [-1, -1]; // indices compared in last step

function defaultArray(size = 50) {
  return Array.from({ length: size }, (_, i) => i + 1);
}

function shuffleArray(a) {
  const res = a.slice();
  for (let i = res.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [res[i], res[j]] = [res[j], res[i]];
  }
  return res;
}

function initArray() {
  arr = shuffleArray(defaultArray());
  resetSortState();
}

function resetSortState() {
  sortState = { i: 0, j: 0, n: arr.length };
  lastCompared = [-1, -1];
}

function isSorted() {
  for (let k = 0; k < arr.length - 1; k++) {
    if (arr[k] > arr[k + 1]) return false;
  }
  return true;
}

/**
 * Performs exactly one comparison (and possibly swap) of bubble sort.
 * @returns {boolean} true if array is fully sorted after this step.
 */
function sortStep() {
  if (isSorted()) return true;
  if (!sortState) resetSortState();

  const { i, j, n } = sortState;
  if (i >= n - 1) {
    sortState = null;
    return true;
  }

  lastCompared = [j, j + 1];
  if (arr[j] > arr[j + 1]) {
    [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
  }

  // advance state
  sortState.j++;
  if (sortState.j >= n - i - 1) {
    sortState.i++;
    sortState.j = 0;
  }

  return false;
}

/* ---------- Rendering ---------- */
const barsEl = document.getElementById('bars');

function render(highlight = []) {
  if (!barsEl) return;
  const maxVal = Math.max(...arr, 1);
  barsEl.innerHTML = '';
  arr.forEach((val, idx) => {
    const bar = document.createElement('div');
    bar.className = 'bar';
    bar.style.height = `${(val / maxVal) * 100}%`;
    if (highlight.includes(idx)) bar.classList.add('compare');
    barsEl.appendChild(bar);
  });
}

/* ---------- UI Event Handlers ---------- */
let animating = false;
let animationId = null;

async function runSortAnimation() {
  if (animating) return;
  animating = true;
  setButtonsDisabled(true);

  while (!sortStep()) {
    render(lastCompared);
    await sleep(10); // speed control
  }
  render(); // final render
  animating = false;
  setButtonsDisabled(false);
}

function sleep(ms) {
  return new Promise(res => setTimeout(res, ms));
}

function setButtonsDisabled(disabled) {
  document.getElementById('sort').disabled = disabled;
  document.getElementById('shuffle').disabled = disabled;
  document.getElementById('reset').disabled = disabled;
}

document.getElementById('sort').addEventListener('click', runSortAnimation);
document.getElementById('shuffle').addEventListener('click', () => {
  if (animating) return;
  arr = shuffleArray(arr);
  resetSortState();
  render();
});
document.getElementById('reset').addEventListener('click', () => {
  if (animating) return;
  initArray();
  render();
});

/* ---------- Public API (window.viz) ---------- */
window.viz = {
  array: () => arr.slice(),
  setArray: (a) => {
    if (!Array.isArray(a)) throw new Error('setArray expects an array');
    arr = a.slice();
    resetSortState();
    render();
  },
  sortStep: () => sortStep(),
  sorted: () => isSorted()
};

/* ---------- Initialisation ---------- */
initArray();
render();
</script>
</body>
</html>
